+ * @param {number} page One-based page number; must be a positive integer.
+ * @param {number} pageSize Page size; must be a positive integer.
+ * @returns {{items: Array<unknown>, total: number, pageCount: number}} A copied
+ *   slice of the requested page plus the totals. An empty collection yields
+ *   `pageCount: 0`; a page beyond the end yields an empty `items` array rather
+ *   than an error.
+ * @throws {RangeError} If `page` or `pageSize` is not a positive integer
+ *   (covers `0`, negatives, fractions, `NaN`, and `Infinity`).
+ */
+export function paginate(items, page, pageSize) {
+  if (items == null || typeof items.length !== 'number') {
+    throw new TypeError('items must be an array-like collection');
+  }
+  if (!Number.isSafeInteger(page) || page < 1) {
+    throw new RangeError(`page must be a positive integer, received: ${String(page)}`);
+  }
+  if (!Number.isSafeInteger(pageSize) || pageSize < 1) {
+    throw new RangeError(`pageSize must be a positive integer, received: ${String(pageSize)}`);
+  }
+
+  const total = items.length;
+  const pageCount = Math.ceil(total / pageSize);
+  const start = (page - 1) * pageSize;
+
+  // slice() copies, so callers cannot alias or mutate the source collection.
+  return { items: Array.prototype.slice.call(items, start, start + pageSize), total, pageCount };
