+import test from 'node:test'; import assert from 'node:assert/strict';
+import {csvCell} from '../src/csv.mjs';
+
+// Every assertion below pins the EXACT returned string (strict equality), not a
+// loose or round-tripped match. Expected values are derived from the documented
+// contract of csvCell: stringify the value, then wrap in double quotes and
+// double any embedded quote when the text contains a comma, quote, or newline.
+
+test('csvCell passes plain strings through unquoted', () => {
+  assert.equal(csvCell('hello'), 'hello');
+  assert.equal(csvCell('abc'), 'abc');
+  assert.equal(csvCell(' padded '), ' padded ');           // spaces are preserved, not trimmed
+  assert.equal(csvCell('café 42'), 'café 42');            // non-ASCII is not escaped
+  assert.equal(csvCell('a-b_c.d/e'), 'a-b_c.d/e');        // other punctuation needs no quoting
+});
+
+test('csvCell converts numbers to their decimal string form', () => {
+  assert.equal(csvCell(42), '42');
+  assert.equal(csvCell(0), '0');
+  assert.equal(csvCell(-7), '-7');
+  assert.equal(csvCell(3.5), '3.5');
+  assert.equal(csvCell(1e21), '1e+21');                   // String(...) semantics, not a locale format
+  assert.equal(csvCell(Number.NaN), 'NaN');
+  assert.equal(csvCell(Number.POSITIVE_INFINITY), 'Infinity');
+});
+
+test('csvCell stringifies non-string primitives', () => {
+  assert.equal(csvCell(true), 'true');
+  assert.equal(csvCell(false), 'false');
+  assert.equal(csvCell(null), 'null');
+  assert.equal(csvCell(undefined), 'undefined');
+  assert.equal(csvCell(10n), '10');
+  assert.equal(csvCell(Symbol('s')), 'Symbol(s)');
+});
+
+test('csvCell leaves an empty string empty and unquoted', () => {
+  assert.equal(csvCell(''), '');
+  // An empty field needs no quotes at all: the value is returned verbatim.
+  assert.notEqual(csvCell(''), '""');
+  assert.equal(csvCell([].join('')), '');                  // another empty-string route
+});
+
+test('csvCell quotes a cell containing a comma', () => {
+  assert.equal(csvCell('a,b'), '"a,b"');
+  assert.equal(csvCell(','), '","');
+  assert.equal(csvCell(',,'), '",,"');
+  assert.equal(csvCell('one,two,three'), '"one,two,three"');
+  assert.equal(csvCell('no-comma-here'), 'no-comma-here'); // control: still unquoted
+});
+
+test('csvCell quotes a cell containing a newline', () => {
+  assert.equal(csvCell('a\nb'), '"a\nb"');
+  assert.equal(csvCell('\n'), '"\n"');
+  assert.equal(csvCell('line1\nline2\nline3'), '"line1\nline2\nline3"');
+  assert.equal(csvCell('\r\n'), '"\r\n"');                // CRLF is quoted; the \n match is sufficient
+  assert.equal(csvCell('trailing\n'), '"trailing\n"');
+  assert.equal(csvCell('no-newline-here'), 'no-newline-here'); // control: still unquoted
+});
+
+test('csvCell escapes embedded double quotes by doubling them', () => {
+  assert.equal(csvCell('"'), '""""');                      // one quote -> 2 escaped + 2 delimiters
+  assert.equal(csvCell('say "hi"'), '"say ""hi"""');
+  assert.equal(csvCell('""'), '""""""');                   // two quotes -> 4 escaped + 2 delimiters
+  assert.equal(csvCell('a"b'), '"a""b"');
+  assert.equal(csvCell("it's"), "it's");                   // apostrophe is not a CSV delimiter
+});
+
+test('csvCell combines quoting and escaping for mixed special characters', () => {
+  assert.equal(csvCell('a,b\n"c"'), '"a,b\n""c"""');
+  assert.equal(csvCell('"quoted", plain'), '"""quoted"", plain"'); // leading quote is escaped too
+  assert.equal(csvCell('name,value\n"x",1'), '"name,value\n""x"",1"');
+});
+
+test('csvCell always returns a string', () => {
+  for (const value of ['plain', 42, '', 'a,b', 'a\nb', '"q"']) {
+    assert.equal(typeof csvCell(value), 'string');
+  }
+});
